#define FOV 		60.0
const float MINIMUM_HIT_DISTANCE = 0.0001;

float flexTime(){
    return 4.0*(iTime+2.0*sin(iTime*.5));
}

float sdPlane( vec3 p, vec3 n, float h )
{
  // n must be normalized
  return dot(p,n) + h;
}


float displace(vec3 p,float r){
    float t = iTime*5.;
    return 0.01+0.01*sin(mod((3.+0.1*r)*p.y+t,PI*2.));
}

float sdSphere( vec3 p, float s )
{
  return (length(p)-s)+displace(p,s);
}

float sdInvertedSphere( vec3 p, float s )
{
  return -(length(p)-s);
}

float opSubtraction( float d1, float d2 )
{
    return max(-d1,d2);
}

float opUnion( float d1, float d2 )
{
    return min(d1,d2);
}

float opIntersection( float d1, float d2 )
{
    return max(d1,d2);
}

vec2 soap_bubbles( vec3 p,int lastType){
    float m=100000.;
    float wall = 0.001;
    float type = 0.;
    vec4 cuts[bubbleCount];
    vec4 bubbles[bubbleCount];
    for(int i=0; i<bubbleCount; i++){
        vec4 bubble = texture(iChannel2,vec2(float(i)+0.25,0.25)/iResolution.xy);
        vec3 q = p-bubble.xyz;
        float soap =sdSphere(q,bubble.w);
        float hollow =sdSphere(q,bubble.w-wall);
        float shell = opSubtraction(hollow,soap);
        if(soap<m && (i+1)!=lastType ){
            for(int j=0; j<bubbleCount; j++){
                vec4 cut = cuts[j]=texture(iChannel2, vec2(float(i)+0.25,float(j)+2.25)/iResolution.xy);
                vec4 other = bubbles[j] = texture(iChannel2, vec2(float(j)+0.25, 0.25)/iResolution.xy);
                if(cut != vec4(0) && j!=i){

                    if(other.w<=bubble.w){
                        vec3 q2 = p-cut.xyz;

                        float middleWall =opIntersection(soap,sdSphere(q2,cut.w+wall));
                        shell = opUnion(shell,middleWall);
                    }
                }
            }
            for(int j=0; j<bubbleCount; j++){
                vec4 cut = cuts[j];
                vec4 other = bubbles[j];
                if(cut != vec4(0) && j!=i){

                    if(other.w<=bubble.w){
                        vec3 q2 = p-cut.xyz;
                        shell = opSubtraction(sdSphere(q2,cut.w),shell);
                    }else{
                        vec3 q2 = p-other.xyz;
                        shell = opSubtraction(sdSphere(q2, other.w), shell);
                    }
                }
            }


            if(shell<m){
                m=shell;
                type = float(i+1);
            }
        }
    }
    return vec2(type,m);
}


vec4 skyColor(in vec3 ro, in vec3 rd){
    return texture(iChannel0, normalize(rd));
}

vec4 bubbleColor(in vec3 ro, in vec3 rd){
    return texture(iChannel1, flexTime()*0.003+0.0325*ro.xy+0.03*(rd.zx+rd.yz+rd.yx));
}


vec2 map_the_world(in vec3 p, int lastType){
    return soap_bubbles(p, lastType);
}


vec3 calculate_normal(in vec3 p,int lastType){
    const vec3 small_step = vec3(0.00001, 0.0, 0.0);
    float gradient_x = map_the_world(p + small_step.xyy, lastType).y - map_the_world(p - small_step.xyy, lastType).y;
    float gradient_y = map_the_world(p + small_step.yxy, lastType).y - map_the_world(p - small_step.yxy, lastType).y;
    float gradient_z = map_the_world(p + small_step.yyx, lastType).y - map_the_world(p - small_step.yyx, lastType).y;
    vec3 normal = vec3(gradient_x, gradient_y, gradient_z);
    return normalize(normal);
}


vec4 ray_march(in vec3 ro, in vec3 rd){
    const int NUMBER_OF_STEPS = 64;
    int lastType = 0;
    int lastType_reflected = 0;

    const float MAXIMUM_TRACE_DISTANCE = 14.0;
    float watereffect = 0.;
    vec3 light_position = vec3(0,1,0);
    vec3 ro_reflected = vec3(0);
    vec3 rd_reflected = vec3(0);
    float reflection_multiplier = 0.0;
    vec3 current_position_reflected = vec3(0);
    vec3 current_position = ro;
    float total_distance_traveled = 0.;
    for (int i = 0; i < NUMBER_OF_STEPS; ++i)
    {
        vec2 distance_to_closest = map_the_world(current_position,lastType);
        current_position += rd*distance_to_closest.y;
        total_distance_traveled+=distance_to_closest.y;
        if(ro_reflected == vec3(0) && distance_to_closest.y < MINIMUM_HIT_DISTANCE) {

            vec3 normal = calculate_normal(current_position, lastType);    
            rd_reflected =normalize(reflect(rd, normal));
            ro_reflected = current_position;
            float ref = abs(dot(normalize(rd),cross(light_position,normal)));
            reflection_multiplier = ref;

        }
        if (distance_to_closest.y < MINIMUM_HIT_DISTANCE && int(distance_to_closest.x) != lastType) 
        {

            vec3 normal = calculate_normal(current_position, lastType);
            ro=current_position;
            float fIn = 1.4;
            float fOut= 1.0;
            rd = normalize((fOut/fIn)*(cross(normal,cross(-normal,rd))-normal*sqrt(fOut-pow(fOut/fIn,2.0)*dot(cross(normal,rd),cross(normal,rd)))));
            //rd = normalize((fIn/fOut)*(cross(-normal,cross(normal,rd))-normal*sqrt(fIn-pow(fIn/fOut,2.0)*dot(cross(normal,rd),cross(normal,rd)))));
            lastType = int(distance_to_closest.x);
        }
        if (total_distance_traveled > MAXIMUM_TRACE_DISTANCE )
        {
            break;
        } 
    }
    return mix((1.0-reflection_multiplier)*skyColor(ro,rd)+reflection_multiplier*2.*bubbleColor(ro_reflected,rd_reflected)*((ro_reflected!=vec3(0))?vec4(skyColor(ro_reflected,rd_reflected).xyz,0.0):vec4(0)),vec4(0.0,0.0,0.1,1.0),watereffect);
}

vec4 samplePixel(in vec2 fragCoord){
    float a = mod(-iTime*.1 +iMouse.x*PI*2./iResolution.x,PI*2.);
    vec2 uv = (2.*(fragCoord.xy)/iResolution.y-1.) * tan (radians (FOV)/2.0);
	float b = mod(0.2*sin(iTime*0.321)+iMouse.y*PI*0.5/iResolution.y-PI*0.125,PI*2.);
    float bs = sin(b);
    float bc = cos(b);
    float as = sin(a);
    float ac = cos(a);
    vec3 fw = vec3 (bc*as, bs, bc*ac);			// forward
    vec3 lf = vec3(ac,0, -as);
    vec3 up = normalize(cross(fw,lf));
    //vec3 up = vec3 (0.0, 1.0, 0.0);			// up 
	//vec3 lf =normalize(cross (up, fw)); 					// left
	vec3 ro = 9.*vec3(-as,0,-ac); // ray origin
	vec3 rd = normalize ((uv.x-.5) * lf + uv.y * up +fw) ; 		// ray direction
    vec4 march = ray_march(ro,rd);
    return vec4(march.xyz,1.0);
}

vec4 superSamplePixel(in vec2 fragCoord){
    vec2 step = vec2(.5);
    vec4 sum=vec4(0);
    for(int i=0;i<2;i++){
        for(int j=0; j<2;j++){
            sum+=samplePixel(fragCoord+vec2(i,j)*step);
        }
    }
    return sum*0.25;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    fragColor = samplePixel(fragCoord);
}

