float myTimeDelta(){
    return iTimeDelta*0.125;
}
vec3 hash33( uvec3 x )
{
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;

    return vec3(x)*(1.0/float(0xffffffffU));
}

bool collide(vec4 bubblea, vec4 bubbleb){
    vec3 diff = bubbleb.xyz-bubblea.xyz;
    float len = length(diff);
    return len< bubblea.w+bubbleb.w;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    if(fragCoord.x<float(bubbleCount+1) && fragCoord.y<3.0+float(bubbleCount)){
        if(iFrame == 0){
            if( fragCoord.y<1.0){
                fragColor =vec4(100,0,9,0)+vec4(hash33(uvec3(int(iTime*79351.)+113,int(fragCoord.x*iResolution.x)+1773,111))*vec3(7,2,7),0.02+hash33(uvec3(int(iTime*19343.),int(iTime*343.),int(fragCoord.x))).x);
            }else if (fragCoord.y<2.0){
                fragColor = vec4(0);
            }
        }
        else{
            vec4 bubblea = texture(iChannel0,vec2(fragCoord.x+0.25,0.25)/iResolution.xy);
            vec4 speedChange = 0.003*(vec4(-0.5,-0.5,-0.5,0)+vec4(hash33(uvec3(iFrame+113,int(fragCoord.x*iResolution.x)+1773,111)),0.));
            vec4 speed =  speedChange+texture(iChannel0,vec2(fragCoord.x+0.25,1.25)/iResolution.xy);
            bubblea+=speed*myTimeDelta()*60.;
            vec4 cuts[16]; 
            for(int i=0; i<bubbleCount; i++){
                vec4 bubbleb = texture(iChannel0,vec2(float(i)+0.25,0.25)/iResolution.xy);
                if(i!=int(fragCoord.x) &&collide(bubblea,bubbleb)){
                      float massa = 4. * PI * bubblea.w*bubblea.w;
                      float massb = 4. * PI * bubbleb.w*bubbleb.w;
                      float ra = bubblea.w;
                      float rb = bubbleb.w;
                      float desiredDistance = sqrt(
                        ra * ra + rb * rb - 2. * ra * rb * cos(PI / 3.)
                      );
                      float dist = length(bubbleb.xyz-bubblea.xyz);
                      float change = (desiredDistance - dist);
                      float changea = (change * massb) / (massa + massb);
                      float changeb = (change * massa) / (massa + massb);
                      vec3 direction =normalize(bubblea.xyz-bubbleb.xyz);
                      vec3 gravityDiff = bubbleb.xyz-vec3(0,(ra<rb?1.:-1.)*desiredDistance,0)-bubblea.xyz;
                      float gravityChange= length(gravityDiff)*massb/(massa+massb);
                      vec3 gravityDirection= normalize(gravityDiff);
                      vec3 speedDiff = gravityDirection*gravityChange*0.02 + direction*changea*0.2;

                      vec3 gravityDiffB = bubblea.xyz-vec3(0,(ra>rb?1.:-1.)*desiredDistance,0)-bubbleb.xyz;
                      float gravityChangeB= length(gravityDiffB)*massa/(massa+massb);
                      vec3 gravityDirectionB= normalize(gravityDiffB);
                      vec3 speedDiffB = gravityDirectionB*gravityChangeB*0.02 - direction*changeb*0.2;


                      bubblea.xyz += speedDiff;
                      bubbleb.xyz += speedDiffB;
                      ///* This is physically more correct
                      float rc = (ra<rb?changea+sqrt(ra*rb/(rb-ra)):changeb+sqrt(ra*rb/(ra-rb)));

                      vec3 bubblec =bubblea.xyz-direction*sqrt(ra*ra+rc*rc+rc*rb);
                      if(ra<rb){
                          bubblec = bubbleb.xyz-direction*sqrt(rb*rb+rc*rc+rc*ra);
                      }
                      cuts[i]= vec4(bubblec,rc);

                }
                else{
                    cuts[i]=vec4(0);
                }
            }
            speed-=speed*0.04*myTimeDelta()*60.; // friction
            if(iFrame%(bubbleCount*8) == 0 && (iFrame/(bubbleCount*8))%bubbleCount == int(fragCoord.x)){
                vec3 r = hash33(uvec3(int(iTime*77351.)+321,int((fragCoord.x+float(bubbleCount))*iResolution.x)+1771,113));
                vec3 r2 = hash33(uvec3(int(iTime*77351.)+321,int(fragCoord.x*iResolution.x)+1771,113));
                bubblea =vec4(5.*(r.x-0.5),-7.+5.*r.y,5.0*(r.z-0.5),r.z+r.x*0.8+0.1);
                speed = vec4((r2.y-0.5)*0.15,0.15+r2.x*0.15,(r2.z-0.5)*0.15,0);
            }
            if( fragCoord.y<1.0){
                fragColor = bubblea;
            }else if (fragCoord.y<2.0){
                fragColor = speed;
            }else if (fragCoord.y<3.0+float(bubbleCount)){
                fragColor = cuts[int(fragCoord.y-2.0)];
            }
        }
    }else{
        fragColor = vec4(0.0,0.0,0.0,1.0);
    }
}
